BEGIN;

ALTER TABLE gyms ADD COLUMN timezone VARCHAR(64) NOT NULL DEFAULT 'America/Argentina/Buenos_Aires';
ALTER TABLE gyms ADD CONSTRAINT chk_gyms_timezone CHECK (timezone <> '');

CREATE TABLE activities (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, gym_id BIGINT NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, title VARCHAR(150) NOT NULL, description TEXT, banner_url TEXT, participation_mode VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', is_visible BOOLEAN NOT NULL DEFAULT FALSE, default_max_capacity INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_activities_mode CHECK (participation_mode IN ('OPEN','GROUP_ONLY','HYBRID')), CONSTRAINT chk_activities_status CHECK (status IN ('DRAFT','ACTIVE','SUSPENDED','ARCHIVED')), CONSTRAINT chk_activities_capacity CHECK (default_max_capacity IS NULL OR default_max_capacity BETWEEN 1 AND 1000));
CREATE TABLE activity_schedules (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, activity_id BIGINT NOT NULL REFERENCES activities(id) ON DELETE CASCADE, day_of_week SMALLINT NOT NULL, starts_at TIME NOT NULL, ends_at TIME NOT NULL, max_capacity INTEGER, active_from DATE NOT NULL, active_until DATE, CONSTRAINT uq_activity_schedules_slot UNIQUE (activity_id,day_of_week,starts_at,active_from), CONSTRAINT chk_activity_schedules_day CHECK (day_of_week BETWEEN 1 AND 7), CONSTRAINT chk_activity_schedules_interval CHECK (ends_at > starts_at), CONSTRAINT chk_activity_schedules_capacity CHECK (max_capacity IS NULL OR max_capacity BETWEEN 1 AND 1000), CONSTRAINT chk_activity_schedules_dates CHECK (active_until IS NULL OR active_until >= active_from));
CREATE TABLE activity_schedule_instructors (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, schedule_id BIGINT NOT NULL REFERENCES activity_schedules(id) ON DELETE CASCADE, gym_coach_id BIGINT NOT NULL REFERENCES gym_coaches(id), CONSTRAINT uq_activity_schedule_instructors UNIQUE (schedule_id,gym_coach_id));
CREATE TABLE activity_groups (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, activity_id BIGINT NOT NULL REFERENCES activities(id) ON DELETE CASCADE, name VARCHAR(150) NOT NULL, join_policy VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', max_members INTEGER, CONSTRAINT uq_activity_groups_name UNIQUE (activity_id,name), CONSTRAINT chk_activity_groups_policy CHECK (join_policy IN ('OPEN','REQUEST_ONLY')), CONSTRAINT chk_activity_groups_status CHECK (status IN ('ACTIVE','PAUSED','ARCHIVED')), CONSTRAINT chk_activity_groups_capacity CHECK (max_members IS NULL OR max_members BETWEEN 1 AND 1000));
CREATE TABLE activity_group_schedules (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES activity_groups(id) ON DELETE CASCADE, schedule_id BIGINT NOT NULL REFERENCES activity_schedules(id) ON DELETE CASCADE, CONSTRAINT uq_activity_group_schedules UNIQUE (group_id,schedule_id));
CREATE TABLE activity_group_memberships (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES activity_groups(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id), start_date DATE NOT NULL, end_date DATE, CONSTRAINT chk_activity_group_memberships_dates CHECK (end_date IS NULL OR end_date >= start_date));
CREATE UNIQUE INDEX uq_activity_group_memberships_active ON activity_group_memberships(group_id,user_id) WHERE end_date IS NULL;
CREATE TABLE activity_group_join_requests (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES activity_groups(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMPTZ, reviewed_by_user_id BIGINT REFERENCES users(id), CONSTRAINT chk_activity_group_join_requests_status CHECK (status IN ('PENDING','APPROVED','REJECTED','CANCELLED')));
CREATE UNIQUE INDEX uq_activity_group_join_requests_pending ON activity_group_join_requests(group_id,user_id) WHERE status='PENDING';
CREATE TABLE activity_occurrences (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, schedule_id BIGINT NOT NULL REFERENCES activity_schedules(id) ON DELETE CASCADE, occurrence_date DATE NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, max_capacity INTEGER, status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED', CONSTRAINT uq_activity_occurrences_schedule_date UNIQUE (schedule_id,occurrence_date), CONSTRAINT chk_activity_occurrences_interval CHECK (ends_at > starts_at), CONSTRAINT chk_activity_occurrences_capacity CHECK (max_capacity IS NULL OR max_capacity BETWEEN 1 AND 1000), CONSTRAINT chk_activity_occurrences_status CHECK (status IN ('SCHEDULED','CANCELLED','COMPLETED')));
CREATE TABLE activity_reservations (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, occurrence_id BIGINT NOT NULL REFERENCES activity_occurrences(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, cancelled_at TIMESTAMPTZ, CONSTRAINT chk_activity_reservations_status CHECK (status IN ('CONFIRMED','CANCELLED')));
CREATE UNIQUE INDEX uq_activity_reservations_confirmed ON activity_reservations(occurrence_id,user_id) WHERE status='CONFIRMED';

COMMIT;
